import json, zipfile, re, os, shutil

# 5a. Load JSON values
with open('/root/training_feedback.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# 5b. Build replacement map - use DOUBLE braces to match template
replacements = {}
for key, value in data.items():
    placeholder = f'{{{{{key}}}}}'  # {{key}}
    if key == '참석자수':
        # Digits only
        digits = re.sub(r'\D', '', str(value))
        replacements[placeholder] = digits
    elif key == '만족도':
        # Extract numeric score, format as X.X점 (5.0점 만점)
        m = re.search(r'[0-9]+(?:\.[0-9]+)?', str(value))
        score = m.group(0) if m else str(value)
        replacements[placeholder] = f'{score}점 (5.0점 만점)'
    elif key == '종합의견':
        replacements[placeholder] = str(value) + ' 후속 심화반 검토 요망.'
    else:
        replacements[placeholder] = str(value)

print('Replacement map:', replacements)

# 5c. Process every file in the ZIP
template_path = '/tmp/hwpx_work/template.zip'
output_path = '/root/training_feedback_ready.hwpx'

with zipfile.ZipFile(template_path, 'r') as zin:
    with zipfile.ZipFile(output_path, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
        # First, write mimetype uncompressed if present
        mimetype_info = None
        other_infos = []
        for info in zin.infolist():
            if info.filename == 'mimetype':
                mimetype_info = info
            else:
                other_infos.append(info)

        if mimetype_info:
            zout.writestr(mimetype_info, zin.read(mimetype_info.filename), compress_type=zipfile.ZIP_STORED)

        for info in other_infos:
            raw = zin.read(info.filename)
            try:
                text = raw.decode('utf-8')
            except UnicodeDecodeError:
                text = None

            if text and '{{' in text:
                # Perform replacements
                for placeholder, replacement in replacements.items():
                    text = text.replace(placeholder, replacement)

                # Remove lineSegArray elements (case-insensitive tag matching for any namespace prefix)
                text = re.sub(r'<(\w+):linesegarray[^>]*>.*?</\1:linesegarray>', '', text, flags=re.DOTALL | re.IGNORECASE)

                # Verify no placeholders remain
                if '{{' in text:
                    raise ValueError(f'Placeholder remains in {info.filename}')

                raw = text.encode('utf-8')

            zout.writestr(info, raw)

print(f'Output written to {output_path}')

# 5f. Validate
with zipfile.ZipFile(output_path, 'r') as z:
    print('Valid ZIP, entries:', len(z.namelist()))
    for name in z.namelist():
        data = z.read(name)
        try:
            text = data.decode('utf-8')
            if '{{' in text:
                print(f'ERROR: placeholder remains in {name}')
        except:
            pass

    # Verify transformed values
    all_text = ''
    for name in z.namelist():
        data = z.read(name)
        try:
            text = data.decode('utf-8')
            all_text += text + '\n'
        except:
            pass

    assert '32' in all_text, '참석자수 value missing'
    assert '4.5점 (5.0점 만점)' in all_text, '만족도 format missing'
    assert '후속 심화반 검토 요망.' in all_text, '종합의견 suffix missing'

    print('All verifications passed.')

    # Print paragraph text content
    for name in z.namelist():
        if name.endswith('.xml'):
            data = z.read(name)
            try:
                text = data.decode('utf-8')
                # Simple regex to extract text between <hp:t> tags
                paragraphs = re.findall(r'<hp:t>([^<]+)</hp:t>', text)
                if paragraphs:
                    print(f'--- {name} ---')
                    for p in paragraphs:
                        print(p)
            except:
                pass

